import {freshDecoration,validDecoration} from './seasonal-decor.mjs';
import {freshBusiness,validBusiness,STAFF} from './alp-business.mjs';
import {BACKLAND as B} from './alp-landscape-plan.mjs';
import {HOF} from './hof-layout.mjs';
export const UPGRADES={
 hut:{name:'1 · Alphütte erneuern',text:'Ein gedeckter Vorbau mit Blumenkästen und Sitzbank. Der erste Schritt zur Gastwirtschaft.',ingredients:{plank:12,nails:4,stone:6},cost:2000,energy:12},
 restaurant:{name:'2 · Alp-Restaurant',text:'Eigene Gaststube mit Terrasse östlich der Hütte. Vier Tagesgäste können mit selbst gekochten Speisen bewirtet werden.',requires:'hut',ingredients:{plank:16,nails:5,ingot:3},cost:8000,energy:15,plot:'restaurant'},
 spa:{name:'3 · Panorama-Badebereich',text:'Holzdeck mit Sprudelbad auf der östlichen Aussichtsterrasse. Ein Bad regeneriert Energie und Ausdauer.',requires:'restaurant',ingredients:{plank:12,stone:10,ingot:4},cost:12000,energy:15,plot:'spa'},
 playground:{name:'4 · Aussenspielplatz',text:'Holzschaukel und Sandbereich auf einer eigenen Familienterrasse.',requires:'spa',ingredients:{plank:12,cord:6,nails:4},cost:9000,energy:12,plot:'playground'},
 upperfloor:{name:'5 · Weiterer Stock',text:'Eine zusätzliche Gästeetage auf dem Restaurant, ohne weitere Wiesenfläche zu verbrauchen. Zwei Gästeplätze kommen hinzu.',requires:'playground',ingredients:{plank:16,nails:6,cloth:6},cost:14000,energy:15,plot:'restaurant'},
 restaurantPlus:{name:'6 · Restaurant erweitern',text:'Ein verbundener Speisesaal auf der reservierten Nachbarfläche. Vier weitere Gästeplätze.',requires:'upperfloor',ingredients:{plank:18,nails:6,stone:8},cost:18000,energy:15,plot:'restaurantPlus'},
 hotel:{name:'7 · Berghotel Portmann',text:'Ein Berner Holzhaus auf der unteren Ostterrasse mit vier Gästezimmern. Übernachtungen werden im Betrieb verwaltet.',requires:'restaurantPlus',ingredients:{plank:20,nails:6,cloth:8},cost:30000,energy:18,plot:'hotel'},
 pasture:{name:'Zusatzweide',text:'Eine zusammenhängende neue Weide mit Holzzaun, offenem Zugang und Tränke östlich des Hotels.',requires:'hut',ingredients:{plank:12,cord:4,nails:3},cost:7000,energy:10,plot:'pasture'},
 tools:{name:'Bessere Feldgeräte',text:'Eine bessere Sense und ein Werkzeugstand am Heufeld. Mähen braucht nur noch zwei statt fünf Energie.',requires:'hut',ingredients:{ingot:3,handle:2,cord:2},cost:4000,energy:8,plot:'tools'},
 silo:{name:'Grosses Heulager',text:'Ein zusätzlicher Holzsilo am westlichen Hofrand. Der Wintervorrat wächst von 64 auf 256 Portionen.',requires:'hut',ingredients:{plank:16,nails:6,ingot:3},cost:6000,energy:12,plot:'silo'},

 riding:{name:'Jonnys Reitpark ausbauen',text:'Holzgeländer, ein schattiger Sitzplatz und ein eigener Vorbereitungsbereich auf der Reitweide. Jonny und der Grundparcours sind bereits frei.',ingredients:{plank:8,nails:3,cord:4},energy:12},
 corn:{name:'Das Kornfeld erweitern',text:'Zusätzliche Getreidereihen neben der Scheune. Ab dem nächsten Spieltag täglich acht Portionen Körner.',ingredients:{plank:6,grain:4,water:2},energy:10},
 cocoa:{name:'Portmann-Schokoladenbohnen pflanzen',text:'Geschütztes Gewächshaus für die Portmann-Sorte. Benötigt das erweiterte Kornfeld. Ab dem nächsten Spieltag drei Portionen Bohnen.',requires:'corn',ingredients:{plank:10,ingot:2,cloth:3,cocoaSeed:2,water:3},energy:15}
};
export const HARVESTS={basic:{name:'Kornfeld · 160 m²',x:-19,z:8,region:'alp',item:'grain',amount:3},corn:{name:'Erweitertes Kornfeld',x:-19,z:13,region:'alp',item:'grain',amount:8},cocoa:{name:'Portmann-Schokoladenbohnen',...HOF.fields.cocoa.entry,region:'alp',item:'cocoa',amount:3}};
export const freshEstate=()=>({decor:freshDecoration(),business:freshBusiness(),built:Object.fromEntries(Object.keys(UPGRADES).map(k=>[k,0])),harvested:{basic:0,corn:0,cocoa:0}});
export function buildEstate(s,id,exchange){const u=Object.hasOwn(UPGRADES,id)&&UPGRADES[id];if(!u)return{ok:false,message:'Unbekannter Ausbau.'};if(s.position.region!=='alp'||!s.position.inside)return{ok:false,message:'Ausbauten planst und fertigst du an der Werkbank in der Alphütte.'};if(s.estate.built[id])return{ok:false,message:'Dieser Ausbau ist bereits fertig.'};if(u.requires&&!s.estate.built[u.requires])return{ok:false,message:'Voraussetzung: '+UPGRADES[u.requires].name+'.'};const r=exchange(s,{take:u.ingredients,cost:u.cost||0,energy:u.energy,stats:{spent:u.cost||0},reason:'build',ref:id});if(!r.ok)return r;s.estate.built[id]=s.day;s.stats.crafts++;return{ok:true,message:u.name+' abgeschlossen. '+(['corn','cocoa'].includes(id)?'Die erste Ernte reift nach einer Nacht.':'Dein Ausbau ist auf der Alp sichtbar.')};}
export function harvestEstate(s,id,exchange){const h=Object.hasOwn(HARVESTS,id)&&HARVESTS[id];if(!h||s.position.region!==h.region||s.position.inside||Math.hypot(s.position.x-h.x,s.position.z-h.z)>2.5)return{ok:false,message:'Gehe zuerst zum Feldrand.'};if(id!=='basic'&&!s.estate.built[id])return{ok:false,message:'Diesen Anbau musst du zuerst an der Hüttenwerkbank freischalten.'};if(id!=='basic'&&s.estate.built[id]>=s.day)return{ok:false,message:'Frisch gepflanzt. Nach einer Nacht ist die erste Ernte reif.'};if(s.estate.harvested[id]===s.day)return{ok:false,message:'Heute bereits geerntet. Über Nacht wächst Nachschub.'};const r=exchange(s,{give:{[h.item]:h.amount},energy:3});if(!r.ok)return r;s.estate.harvested[id]=s.day;return{ok:true,message:h.amount+' × '+(id==='cocoa'?'Schokoladenbohnen':'Körner')+' geerntet.'};}
export function restByStream(s){if(s.position.region!=='alp'||s.position.inside||Math.hypot(s.position.x-B.camp.entry.x,s.position.z-B.camp.entry.z)>2.5)return{ok:false,message:'Gehe zuerst zur Feuerstelle am Bach.'};if(s.energy>=100&&s.stamina>=100)return{ok:false,message:'Du bist bereits gut erholt. Geniesse den Bach.'};s.energy=Math.min(100,s.energy+25);s.stamina=100;return{ok:true,message:'Am Bergbach gerastet · bis zu 25 Energie und volle Ausdauer.'};}
export function validEstate(e,day){const obj=v=>v&&typeof v==='object'&&!Array.isArray(v),book=(v,keys)=>obj(v)&&Object.keys(v).length===keys.length&&keys.every(k=>Number.isSafeInteger(v[k])&&v[k]>=0&&v[k]<=day);return obj(e)&&(e.decor===undefined||validDecoration(e.decor))&&validBusiness(e.business,day)&&Object.entries(STAFF).every(([k,p])=>!e.business.staff[k]||e.built[p.requires]>0)&&(!e.business.served||e.built.restaurant>0)&&(!e.business.rooms||e.built.hotel>0)&&book(e.built,Object.keys(UPGRADES))&&book(e.harvested,Object.keys(HARVESTS))&&Object.entries(UPGRADES).every(([id,u])=>!e.built[id]||!u.requires||e.built[u.requires]>0&&e.built[id]>=e.built[u.requires])&&(!e.built.cocoa||e.built.corn>0&&e.built.cocoa>=e.built.corn)&&['corn','cocoa'].every(k=>!e.harvested[k]||e.built[k]>0&&e.harvested[k]>e.built[k]);}
